// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 < 1e30 && amount2 < 1e30);
        vm.assume(actor != address(0));

        uint256 total = amount1 + amount2;
        vm.assume(total < 1e30);
        vm.deal(actor, total);

        vm.startPrank(actor);
        c.addToBalance{value: amount1}();
        vm.stopPrank();

        vm.startPrank(actor);
        c.addToBalance{value: amount2}();
        vm.stopPrank();

        uint256 expectedSum = amount1 + amount2;
        uint256 actualBalance = c.getBalance(actor);
        assertTrue(actualBalance == expectedSum);
    }
}
